/* brutal.css — scoped neo-brutalist styles. Only active under .brutal-page. */

@import url('https://fonts.googleapis.com/css2?family=Archivo+Black&family=Space+Grotesk:wght@400;500;700&family=Inter:wght@400;500;600&display=swap');

/* --- Escape Quarto chrome and let the page fill the viewport --- */
body:has(.brutal-page) {
  margin: 0;
  padding: 0;
  background: #f5f1ea;
  overflow-x: hidden;
}

body:has(.brutal-page) #quarto-content,
body:has(.brutal-page) main.content,
body:has(.brutal-page) .page-columns {
  padding: 0 !important;
  margin: 0 !important;
  max-width: none !important;
  width: 100% !important;
  display: block !important;
}

body:has(.brutal-page) #quarto-header,
body:has(.brutal-page) .nav-footer,
body:has(.brutal-page) footer.footer,
body:has(.brutal-page) #title-block-header {
  display: none !important;
}

/* --- Theme tokens (default: cream) --- */
.brutal-page {
  --bg: #f7f2e8;
  --ink: #2b2622;
  --paper: #fffdf8;
  --muted: #877f74;
  --c1: #f0bcc8;
  --c2: #bfddd5;
  --c3: #f2dc94;
  --c4: #d3c8e8;
  --cta-bg: var(--c1);
  --border: 2.5px;
  --shadow-sm: 3px 3px 0 0 var(--ink);
  --shadow-md: 5px 5px 0 0 var(--ink);
  --shadow-lg: 8px 8px 0 0 var(--ink);
}

.brutal-page[data-theme="mono"] {
  --bg: #efece6;
  --ink: #2a2725;
  --paper: #fbf9f5;
  --muted: #7c7670;
  --c1: #c46b5c;
  --c2: #d8d3c9;
  --c3: #c0bcb1;
  --c4: #c46b5c;
  --cta-bg: #c46b5c;
}

.brutal-page[data-theme="neon"] {
  --bg: #1a1a26;
  --ink: #ede7d8;
  --paper: #25253a;
  --muted: #8e8aa3;
  --c1: #c98ab0;
  --c2: #7fb8ad;
  --c3: #c8c97a;
  --c4: #8aa9c9;
  --cta-bg: #c98ab0;
}

.brutal-page[data-theme="earth"] {
  --bg: #ebe1cd;
  --ink: #3a2c1e;
  --paper: #f7eedd;
  --muted: #7a6347;
  --c1: #b97a5e;
  --c2: #97a980;
  --c3: #d2b574;
  --c4: #a8714e;
  --cta-bg: #b97a5e;
}

.brutal-page[data-theme="vapor"] {
  --bg: #2c2848;
  --ink: #ede5ef;
  --paper: #383260;
  --muted: #a8a0c0;
  --c1: #d99cba;
  --c2: #8ab5c5;
  --c3: #e0c887;
  --c4: #ad9bcc;
  --cta-bg: #d99cba;
}

.brutal-page[data-theme="carbon"] {
  --bg: #1c1d22;
  --ink: #e8e3d9;
  --paper: #28292f;
  --muted: #8a8a93;
  --c1: #d99452;
  --c2: #6b8a8d;
  --c3: #c9a87f;
  --c4: #a87547;
  --cta-bg: #d99452;
}

.brutal-page[data-theme="forest"] {
  --bg: #1a2420;
  --ink: #e0e8e0;
  --paper: #243029;
  --muted: #7a8a7e;
  --c1: #a8c490;
  --c2: #c9b485;
  --c3: #d49872;
  --c4: #8aaa92;
  --cta-bg: #a8c490;
}

.brutal-page[data-theme="midnight"] {
  --bg: #161b2e;
  --ink: #e8e6dd;
  --paper: #20253a;
  --muted: #8a93b0;
  --c1: #d4956b;
  --c2: #8aa3c4;
  --c3: #d4c896;
  --c4: #b87a5b;
  --cta-bg: #d4956b;
}

.brutal-page[data-theme="noir"] {
  --bg: #0d0d0e;
  --ink: #ebe7d8;
  --paper: #1c1c1e;
  --muted: #82807a;
  --c1: #c45c5c;
  --c2: #7aa39a;
  --c3: #d4b96a;
  --c4: #9c8fc4;
  --cta-bg: #c45c5c;
}

/* --- Page shell --- */
.brutal-page {
  background: var(--bg);
  color: var(--ink);
  font-family: 'Inter', sans-serif;
  min-height: 100vh;
  width: 100%;
  padding: 1.25rem clamp(1rem, 3vw, 2.25rem) 1.5rem;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  transition: background 0.4s ease, color 0.4s ease;
}

.brutal-page * { box-sizing: border-box; }
.brutal-page a { color: inherit; }

/* --- Top bar (compact) --- */
.brutal-page .brutal-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.55rem 0.85rem 0.55rem 1.25rem;
  border: var(--border) solid var(--ink);
  border-radius: 999px;
  background: var(--paper);
  box-shadow: var(--shadow-sm);
  flex-shrink: 0;
}

.brutal-page .brutal-brand {
  font-family: 'Archivo Black', sans-serif;
  font-size: 1.15rem;
  letter-spacing: 0.05em;
}

.brutal-page .brutal-nav {
  display: flex;
  gap: 1.4rem;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brutal-page .brutal-nav a {
  text-decoration: none;
  border-bottom: 2px solid transparent;
  padding-bottom: 1px;
  transition: border-color 0.15s;
}
.brutal-page .brutal-nav a:hover { border-bottom-color: var(--ink); }

.brutal-page .brutal-controls {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

/* Theme switcher dropdown */
.brutal-page .brutal-theme {
  position: relative;
  font-family: 'Space Grotesk', sans-serif;
}

.brutal-page .brutal-theme-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.45rem 0.85rem;
  border: 2px solid var(--ink);
  border-radius: 999px;
  background: var(--paper);
  color: var(--ink);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  font-family: inherit;
}

.brutal-page .brutal-theme-btn .dot {
  width: 10px; height: 10px;
  border-radius: 999px;
  background: var(--c1);
  border: 1.5px solid var(--ink);
  display: inline-block;
}

.brutal-page .brutal-theme-btn .caret { font-size: 0.6rem; }

.brutal-page .brutal-theme-menu {
  position: absolute;
  top: calc(100% + 0.5rem);
  right: 0;
  list-style: none;
  margin: 0;
  padding: 0.4rem;
  border: 2px solid var(--ink);
  border-radius: 12px;
  background: var(--paper);
  box-shadow: var(--shadow-md);
  min-width: 160px;
  z-index: 100;
}

.brutal-page .brutal-theme-menu[hidden] { display: none; }

.brutal-page .brutal-theme-menu li {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.5rem 0.75rem;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.12s;
}

.brutal-page .brutal-theme-menu li:hover { background: var(--bg); }
.brutal-page .brutal-theme-menu li[data-active="true"] { background: var(--c3); }

.brutal-page .brutal-theme-menu .swatch {
  width: 14px; height: 14px;
  border-radius: 999px;
  border: 1.5px solid var(--ink);
  flex-shrink: 0;
}
.brutal-page .swatch-cream { background: linear-gradient(135deg, #f0bcc8 50%, #bfddd5 50%); }
.brutal-page .swatch-mono { background: linear-gradient(135deg, #d8d3c9 50%, #c46b5c 50%); }
.brutal-page .swatch-earth { background: linear-gradient(135deg, #b97a5e 50%, #97a980 50%); }
.brutal-page .swatch-neon { background: linear-gradient(135deg, #c98ab0 50%, #c8c97a 50%); }
.brutal-page .swatch-vapor { background: linear-gradient(135deg, #d99cba 50%, #8ab5c5 50%); }
.brutal-page .swatch-carbon { background: linear-gradient(135deg, #d99452 50%, #28292f 50%); }
.brutal-page .swatch-forest { background: linear-gradient(135deg, #a8c490 50%, #243029 50%); }
.brutal-page .swatch-midnight { background: linear-gradient(135deg, #d4956b 50%, #20253a 50%); }
.brutal-page .swatch-noir { background: linear-gradient(135deg, #c45c5c 50%, #0d0d0e 50%); }

.brutal-page .brutal-theme-menu .menu-divider {
  height: 1px;
  background: var(--ink);
  opacity: 0.2;
  margin: 0.3rem 0.5rem;
  list-style: none;
  padding: 0;
}
.brutal-page .brutal-theme-menu .menu-label {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 0.4rem 0.75rem 0.2rem;
  color: var(--muted);
  cursor: default;
}
.brutal-page .brutal-theme-menu .menu-label:hover { background: transparent; }

.brutal-page .brutal-contact {
  padding: 0.5rem 1rem;
  background: var(--ink);
  color: var(--bg);
  border: 2px solid var(--ink);
  border-radius: 999px;
  text-decoration: none;
  font-weight: 700;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: transform 0.15s, box-shadow 0.15s, background 0.15s;
}
.brutal-page .brutal-contact:hover {
  transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0 0 var(--c1);
  color: var(--bg);
}

/* --- Main column fills the rest of the viewport --- */
.brutal-page .brutal-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  min-height: 0;
}

/* --- Hero (compact, 2 columns) --- */
.brutal-page .brutal-hero {
  flex: 1;
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  gap: clamp(1rem, 3vw, 2.5rem);
  align-items: stretch;
  position: relative;
  min-height: 0;
}

.brutal-page .hero-text {
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  padding-right: 0.5rem;
}

.brutal-page .eyebrow {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 0.5rem;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.brutal-page .eyebrow::before {
  content: '';
  width: 28px;
  height: 2px;
  background: var(--ink);
  display: inline-block;
}

.brutal-page .brutal-title {
  font-family: 'Archivo Black', sans-serif;
  font-size: clamp(2.75rem, 7.5vw, 6rem);
  line-height: 0.88;
  letter-spacing: -0.025em;
  margin: 0 0 0.9rem 0;
}

.brutal-page .brutal-title .stamp {
  display: inline-block;
  background: var(--c3);
  border: var(--border) solid var(--ink);
  padding: 0 0.25em;
  transform: rotate(-2deg);
  box-shadow: var(--shadow-sm);
  margin-left: 0.1em;
}

.brutal-page .tagline {
  font-family: 'Space Grotesk', sans-serif;
  font-size: clamp(1rem, 1.4vw, 1.2rem);
  font-weight: 500;
  line-height: 1.35;
  margin: 0 0 1rem 0;
  max-width: 32ch;
  color: var(--ink);
}
.brutal-page .tagline .accent { font-weight: 700; }

.brutal-page .roles {
  list-style: none;
  padding: 0;
  margin: 0 0 1.25rem 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.brutal-page .roles li {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.3rem 0.7rem;
  border: 2px solid var(--ink);
  border-radius: 999px;
  background: var(--paper);
}

.brutal-page .roles li:nth-child(1) { background: var(--c1); }
.brutal-page .roles li:nth-child(2) { background: var(--c2); }
.brutal-page .roles li:nth-child(3) { background: var(--c3); }

.brutal-page .brutal-cta {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.85rem 1.6rem;
  background: var(--cta-bg);
  color: var(--ink);
  border: var(--border) solid var(--ink);
  border-radius: 999px;
  box-shadow: var(--shadow-md);
  text-decoration: none;
  font-weight: 700;
  font-size: 0.95rem;
  letter-spacing: 0.04em;
  transition: transform 0.15s, box-shadow 0.15s;
}
.brutal-page .brutal-cta:hover {
  transform: translate(-3px, -3px);
  box-shadow: var(--shadow-lg);
}
.brutal-page .brutal-cta .arrow {
  display: inline-block;
  transition: transform 0.2s;
}
.brutal-page .brutal-cta:hover .arrow { transform: translateX(3px); }

/* --- Hero visual: tilted framed photo with badges --- */
.brutal-page .hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.brutal-page .visual-frame {
  position: relative;
  width: 100%;
  max-width: 560px;
  aspect-ratio: 5 / 4;
  border: var(--border) solid var(--ink);
  border-radius: 8px;
  box-shadow: var(--shadow-lg);
  background: var(--ink);
  overflow: hidden;
  transform: rotate(2deg);
  transition: transform 0.3s ease;
}
.brutal-page .visual-frame:hover { transform: rotate(0deg); }

.brutal-page .visual-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  display: block;
  filter: contrast(1.05);
}

.brutal-page .visual-frame .badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--c3);
  border: 2px solid var(--ink);
  border-radius: 999px;
  padding: 0.3rem 0.7rem;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink);
}

.brutal-page .floating-tag {
  position: absolute;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 12px;
  padding: 0.5rem 0.8rem;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  box-shadow: var(--shadow-sm);
  z-index: 5;
}
.brutal-page .floating-tag.tag-1 {
  top: 8%;
  right: -10px;
  transform: rotate(6deg);
  background: var(--c2);
}
.brutal-page .floating-tag.tag-2 {
  bottom: 12%;
  left: -16px;
  transform: rotate(-5deg);
  background: var(--c1);
}

/* --- Quick links row (compact cards) --- */
.brutal-page .brutal-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.85rem;
  flex-shrink: 0;
}

.brutal-page .brutal-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.85rem 1rem;
  background: var(--paper);
  border: var(--border) solid var(--ink);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  text-decoration: none;
  color: var(--ink);
  transition: transform 0.15s, box-shadow 0.15s;
  position: relative;
  min-height: 70px;
}

.brutal-page .brutal-card:hover {
  transform: translate(-3px, -3px);
  box-shadow: var(--shadow-md);
}

.brutal-page .brutal-card.c1 { background: var(--c1); }
.brutal-page .brutal-card.c2 { background: var(--c2); }
.brutal-page .brutal-card.c3 { background: var(--c3); }
.brutal-page .brutal-card.c4 { background: var(--c4); }

.brutal-page .brutal-card .num {
  font-family: 'Archivo Black', sans-serif;
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  opacity: 0.5;
  margin-right: 0.4rem;
}

.brutal-page .brutal-card h3 {
  font-family: 'Archivo Black', sans-serif;
  font-size: 1.15rem;
  margin: 0;
  line-height: 1;
  flex: 1;
}

.brutal-page .brutal-card .arrow {
  font-family: 'Archivo Black', sans-serif;
  font-size: 1.25rem;
  transition: transform 0.2s;
}
.brutal-page .brutal-card:hover .arrow { transform: translateX(3px); }

/* --- Decorative scattered marks --- */
.brutal-page .scatter {
  position: absolute;
  pointer-events: none;
  user-select: none;
  font-family: 'Archivo Black', sans-serif;
  color: var(--ink);
  opacity: 0.65;
  z-index: 1;
}
.brutal-page .scatter-1 { top: 12%; left: 38%; font-size: 1.3rem; transform: rotate(15deg); }
.brutal-page .scatter-2 { bottom: 18%; left: 48%; font-size: 1rem; color: var(--c1); opacity: 1; }

/* --- Scroll reveal base state --- */
[data-reveal] {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s cubic-bezier(0.22, 1, 0.36, 1),
              transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

[data-reveal].revealed {
  opacity: 1;
  transform: translateY(0);
}

/* Stagger delays */
[data-reveal][data-delay="1"] { transition-delay: 0.08s; }
[data-reveal][data-delay="2"] { transition-delay: 0.16s; }
[data-reveal][data-delay="3"] { transition-delay: 0.24s; }
[data-reveal][data-delay="4"] { transition-delay: 0.32s; }
[data-reveal][data-delay="5"] { transition-delay: 0.40s; }
[data-reveal][data-delay="6"] { transition-delay: 0.48s; }
[data-reveal][data-delay="7"] { transition-delay: 0.56s; }
[data-reveal][data-delay="8"] { transition-delay: 0.64s; }

/* Title: scale + slide */
[data-reveal][data-anim="title"] {
  transform: scale(0.92) translateY(20px);
}
[data-reveal][data-anim="title"].revealed {
  transform: scale(1) translateY(0);
  transition-duration: 0.8s;
}

/* Topbar: slide down */
[data-reveal][data-anim="slide-down"] {
  transform: translateY(-20px);
}
[data-reveal][data-anim="slide-down"].revealed {
  transition-delay: 0s;
}

/* Floating tags: smooth appearance */
.floating-tag {
  transition: transform 0.3s ease;
}

/* Scatter marks: continuous float */
@keyframes float-1 {
  0%, 100% { transform: rotate(15deg) translateY(0); }
  50% { transform: rotate(15deg) translateY(-8px); }
}
@keyframes float-2 {
  0%, 100% { transform: rotate(-5deg) translateY(0); }
  50% { transform: rotate(-5deg) translateY(6px); }
}
.scatter-1 { animation: float-1 3s ease-in-out infinite; }
.scatter-2 { animation: float-2 4s ease-in-out infinite; }

/* CTA: pulse glow after reveal */
.brutal-cta.revealed {
  animation: cta-pulse 2s ease-in-out 0.8s 1;
}
@keyframes cta-pulse {
  0%, 100% { box-shadow: var(--shadow-md); }
  50% { box-shadow: var(--shadow-lg), 0 0 0 4px var(--c1); }
}

/* --- Accessibility: reduced motion --- */
@media (prefers-reduced-motion: reduce) {
  [data-reveal] {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
  .scatter-1, .scatter-2 { animation: none !important; }
  .brutal-cta.revealed { animation: none !important; }
}

/* --- Responsive --- */
@media (max-width: 920px) {
  .brutal-page .brutal-hero { grid-template-columns: 1fr; gap: 1.25rem; }
  .brutal-page .brutal-cards { grid-template-columns: repeat(2, 1fr); }
  .brutal-page .visual-frame { max-width: 420px; transform: none; }
  .brutal-page .brutal-nav { display: none; }
  .brutal-page .floating-tag { display: none; }
}

@media (max-width: 600px) {
  .brutal-page .brutal-cards { grid-template-columns: 1fr; }
  .brutal-page .brutal-title { font-size: clamp(2.5rem, 12vw, 4rem); }
}

/* styles.css */

/* 1. IMPORT FONTS */
/* Space Grotesk for Headings (Tech/Modern feel), Inter for Body */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600&family=Space+Grotesk:wght@500;700&display=swap');

:root {
  --hero-height: 50vh;
  --radius-lg: 12px;
  --transition-fast: 0.3s ease;
}

body {
  font-family: 'Inter', sans-serif;
  -webkit-font-smoothing: antialiased;
  line-height: 1.6;
}

/* 2. TYPOGRAPHY HIERARCHY */
h1, h2, h3, h4, h5, h6, .navbar-brand {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  letter-spacing: -0.03em; /* Tight tracking for modern feel */
}

/* Hero text - ensure visibility in both light and dark modes */
.hero-title,
.hero-subtitle {
  color: #ffffff;
}

h1.title {
  font-weight: 800;
}

/* 3. HERO SECTION */
.hero-section {
  position: relative;
  background-color: #2a2a2a; /* Fallback color while image loads */
  background-image: url('images/wide_maroc.jpg');
  background-size: cover;
  background-position: center;
  border-radius: var(--radius-lg);
  overflow: hidden;
  /* Flexbox for alignment instead of <br> tags */
  display: flex;
  align-items: center; /* Vertically center */

  justify-content: flex-end; /* Align text to right */
  min-height: var(--hero-height);
  padding: 6rem;
  margin-bottom: 3rem;
  margin-top: 3rem;
  box-shadow: 0 10px 30px rgba(0,0,0,0.15);
}

/* Overlay for better text readability if image is busy */
.hero-section::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(to right, transparent 0%, rgba(0,0,0,0.6) 100%);
  z-index: 1;
}

/* 1. Make the container a flex row to put items side-by-side */
.hero-content {
  position: relative; /* 'position: left' is invalid CSS */
  z-index: 2;
  text-align: left; /* Left align looks best for side-by-side */
  max-width: 700px; /* Increased width to accommodate both elements */

  display: flex;          /* This puts Title and Subtitle next to each other */
  flex-direction: row;    /* Explicitly set row */
  align-items: center;    /* Vertically aligns the subtitle block with the title */
  gap: 4.4rem;              /* Spacing between the Title and the Subtitle */
}

/* 2. Remove bottom margins so they align cleanly */
.hero-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 3.0rem;
  line-height: 1.1;
  font-weight: 300;
  margin: 0;
  text-shadow: 0 4px 10px rgba(0,0,0,0.3);
  white-space: nowrap;
}

/* 3. Change the border from Top to Left to create a vertical divider */
.hero-subtitle {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.8rem;
  font-weight: 300;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  opacity: 0.9;

  /* Reset previous top-border styles */
  margin-top: 0;
  padding-top: 0;
  border-top: none;

  /* Add new left-border styles */
  padding-left: 1.0rem;
  border-left: 1px solid rgba(255,255,255,0.5);
  margin-left: 1.0rem;
  /* Ensure the text inside stacks vertically */
  display: flex;
  flex-direction: column;
  gap: 2.0rem;
  line-height: 4.0;
  white-space: nowrap; 
}

/* 4. CARDS & GRID */
/* Tight grid gap for feature cards */
.feature-grid {
  gap: 0.5rem !important;
}

.feature-card {
  /* 1. VISUALS */
  padding: 1rem;
  border-radius: var(--radius-lg);
  border: 1px solid rgba(0, 0, 0, 0.08);
  background-color: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(12px);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);

  /* 2. LAYOUT - Fixed height for consistency */
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  height: 80px !important;
  min-height: 80px !important;
  max-height: 80px !important;
  overflow: hidden;
  transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
}

/* THE TITLE */
.feature-card h3,
.feature-card h4 {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.2rem;
  font-weight: 700;
  /* Start with 0 margin so it looks centered and tight */
  margin-bottom: 0;
  transition: margin-bottom 0.3s ease;
}

/* Ensure links inside card titles match */
.feature-card h3 a,
.feature-card h4 a {
  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  text-decoration: none;
  color: inherit;
}

/* Card wrapper links */
a.card-link {
  text-decoration: none;
  color: inherit;
  display: block;
}

a.card-link:hover {
  text-decoration: none;
}

/* THE HIDDEN TEXT (New) */
/* This targets paragraphs <p> inside the card */
.feature-card p {
  font-family: 'Inter', sans-serif;
  max-height: 0;                /* Hidden height */
  opacity: 0;                   /* Hidden visibility */
  overflow: hidden;             /* Cut off anything that spills out */
  margin: 0;                    /* No spacing */
  transform: translateY(10px);  /* Push it down slightly */
  transition: all 0.4s ease;
}

/* --- HOVER STATES --- */

.feature-card:hover {
  /* Visual Lift */
  transform: translateY(-5px);
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
  border-color: rgba(0,0,0,0.1);
  /* Allow expansion on hover */
  height: auto !important;
  max-height: 200px !important;
}

.feature-card:hover h3,
.feature-card:hover h4 {
  margin-bottom: 1rem; /* Add space between title and text on hover */
}

.feature-card:hover p {
  max-height: 400px;           /* Arbitrary limit large enough for text */
  opacity: 1;                  /* Fade in */
  transform: translateY(0);    /* Slide up */
}

/* 5. ABOUT PAGE STYLES */

/* Hide Quarto's auto-generated title block on about page */
body.about-page #title-block-header { display: none; }

/* Reduce top padding on about page to reclaim vertical space */
body.about-page #quarto-content { padding-top: 50px; }

