  border-color: rgba(0, 0, 0, 0.15);
  text-decoration: none;
  color: inherit;
}

.portfolio-project-icon {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(113, 178, 128, 0.25), rgba(45, 90, 39, 0.15));
  border-radius: var(--radius-lg);
  font-size: 1.2rem;
  color: #2d5a27;
}

.portfolio-project-body {
  flex: 1;
  min-width: 0;
}

.portfolio-project-body h4 {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.95rem;
  font-weight: 700;
  margin: 0 0 0.25rem 0;
  color: #1a1a1a;
}

.portfolio-project-desc {
  font-family: 'Inter', sans-serif;
  font-size: 0.78rem;
  line-height: 1.4;
  color: #666;
  margin: 0 0 0.5rem 0;
}

.portfolio-project-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.portfolio-tag {
  font-family: 'Inter', sans-serif;
  font-size: 0.65rem;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  background: rgba(113, 178, 128, 0.15);
  color: #2d5a27;
  font-weight: 500;
}

.portfolio-project-arrow {
  flex-shrink: 0;
  opacity: 0;
  transform: translateX(-5px);
  transition: opacity 0.25s ease, transform 0.25s ease;
  color: #555;
  font-size: 1rem;
}

.portfolio-project-card:hover .portfolio-project-arrow {
  opacity: 1;
  transform: translateX(0);
}

/* Portfolio - Dark Mode */
body.quarto-dark .portfolio-project-card {
  background-color: #1e1e1e;
  border: 1px solid #333;
}

body.quarto-dark .portfolio-project-card:hover {
  background-color: #252525;
  border-color: #555;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
}

body.quarto-dark .portfolio-project-icon {
  background: linear-gradient(135deg, rgba(157, 181, 209, 0.2), rgba(100, 140, 180, 0.1));
  color: #9db5d1;
}

body.quarto-dark .portfolio-project-body h4 {
  color: #e0e0e0;
}

body.quarto-dark .portfolio-project-desc {
  color: #a0a0a0;
}

body.quarto-dark .portfolio-tag {
  background: rgba(157, 181, 209, 0.15);
  color: #9db5d1;
}

body.quarto-dark .portfolio-project-arrow {
  color: #a0a0a0;
}

/* Portfolio - Mobile */
@media (max-width: 480px) {
  .portfolio-grid .g-col-md-6 {
    grid-column: span 12 !important;
  }
}
